    scopeDists().filter(d=>DD[d].ewInf).sort((a,b)=>DD[b].ewInf-DD[a].ewInf).slice(0,3).forEach(d=>acts.push(actItem(`${d}: ${DD[d].ewInf} informal e-waste dismantling units`,'Inspection and closure directions','red')));
