    meters=meter('Recyclers filing EPR returns',D.btEpr,100,'%','Battery Rules 2022: returns on the centralised portal')+meter('Informal lead smelting units',D.btInf,0,'units','Lead recovery only by registered recyclers',true)+meter('Districts with a registered recycler',scopeDists().filter(d=>DD[d].btR).length/scopeDists().length*100,100,'%','Waste batteries should reach a registered unit nearby')+meter('Producer collection centres reporting',clamp(60+R('bcr'+where(),0,35),0,100),100,'%','Battery Rules 2022: producers set up take-back');
